char row[5];
int i = 1, n = 4;
for (int j = 0; j < n; j++) {
    if (i == 0 || i == n - 1 || j == 0 || j == n - 1) row[j] = '*';
    else row[j] = ' ';
}
row[n] = '\0';
printf("%s\n", row);

